@R.add('ch10-st2', 'C3', (2, 5), 'numerical')
def threshold(rng, slot):
    svc, th = rng.choice([('a supermarket', 2500), ('a secondary school', 10000), ('a doctor\'s surgery', 3000), ('a cinema', 25000),
                          ('a hospital', 100000), ('a bank branch', 8000), ('a petrol station', 2000)])
    vills = [rng.randint(3, 40) * 100 for _ in range(rng.randint(3, 6))]
    tot = sum(vills)
    town = rng.randint(5, 60) * 100
    pop = tot + town
    ok = pop >= th
    stem = (f'A small town of {town:,} people is the service centre for {len(vills)} villages with populations of ' + ', '.join(f'{v:,}' for v in vills) +
            f'. The threshold population for {svc} is about {th:,}. Calculate the total population of the sphere of influence and state whether the town is likely to support {svc}.')
    return dict(stem=stem, answer=f'{pop:,} people – {"yes, above" if ok else "no, below"} the threshold', type='numerical', marks=3,
                markingKey=f'Villages {tot:,} + town {town:,} = {pop:,} (M1 A1); compared with threshold {th:,} → {"likely to support" if ok else "unlikely to support"} it (R1).', gap='G3')


