K.st('ch12-st1', 'formulating an inquiry question and an action plan',
     terms=[('research question', 'a clear, focused and open question that guides an investigation and can be answered with evidence'),
            ('action plan', 'a step-by-step schedule showing what will be done, when, and with which resources and sources'),
            ('open question', 'a question that cannot be answered with "yes" or "no" and invites explanation or evaluation'),
            ('scope', 'the limits of an investigation, such as the place, time period and group studied'),
            ('hypothesis', 'a testable statement that predicts the answer to a research question'),
            ('relevance', 'how a research question connects to the unit\'s key and related concepts, global context and real-world issues')],
     facts=[('Which of these is the best research question for an MYP investigation?', '"How did the 2015 earthquake affect tourism in Kathmandu between 2015 and 2018?"', ['"Earthquakes – are they bad?"', '"What is tourism?"', '"Tell me everything about Nepal."'], 'It is open, focused on a place, period and impact, and researchable.'),
            ('Which word at the start of a question usually makes it closed?', '"Is"', ['"How"', '"Why"', '"To what extent"'], '"Is" questions can often be answered yes or no.'),
            ('What should an action plan include?', 'Steps, deadlines, sources and how information will be recorded', ['Only the final answer', 'Only the title', 'A list of opinions'], 'Criterion B ii.'),
            ('In MYP I&S, formulating and justifying a research question is part of which criterion?', 'Criterion B – Investigating', ['Criterion A – Knowing and understanding', 'Criterion C – Communicating', 'Criterion D – Thinking critically'], 'B i: formulate a clear and focused research question and justify its relevance.')],
     why=[('Explain why a research question should be focused rather than broad.', 'A focused question (clear place, period, group) can be answered in depth with the time and sources available; a broad question leads to a shallow, descriptive answer.'),
          ('Explain why an action plan helps an investigation succeed.', 'It breaks the task into steps with deadlines, identifies sources early, and lets the student check progress and adjust before running out of time.'),
          ('Explain why a student should justify the relevance of a research question.', 'Justification shows why the question matters – its link to key concepts, the global context and real issues – and shows that it is worth investigating (criterion B i).'),
          ('Explain why closed questions are weak research questions.', 'They can be answered with yes or no or a single fact, so they do not require analysis, evaluation or the use of a range of evidence.')],
     contrast=[('a topic', 'a research question', 'A topic is a broad area of interest (e.g. "migration"); a research question is a specific, open, answerable question within it (e.g. "Why did Syrian refugees settle in Gaziantep, Türkiye, between 2012 and 2016?").'),
               ('a research question', 'a hypothesis', 'A research question asks what you want to find out; a hypothesis is a prediction of the answer that the investigation will test.')],
     misc=[('A good research question should be as broad as possible so you find lots of information.', 'Broad questions lead to shallow answers; a focused question with a clear scope allows deep, evaluative investigation.'),
           ('An action plan is only written after the research is finished.', 'It is written at the start to guide the research and updated as the investigation develops.'),
           ('A research question must have a single correct answer.', 'Good I&S research questions are often open and allow a supported judgement rather than one fact.')],
     cases=[('a Grade 8 investigation into the local river', 'A student narrowed "rivers" to "How does water quality change downstream of the town\'s treatment works on the River Kennet?" and planned three site visits.', 'refining a topic into a research question', 'adding a place, variable and measurable focus made the question researchable.'),
            ('a class investigation on the Silk Road', 'A student changed "What was the Silk Road?" to "How did Buddhism spread to China along the Silk Road between 100 and 600 CE?"', 'focusing a historical question', 'a clear time span and concept (cultural diffusion) made it possible to use specific sources.')],
     evaluate=[('The research question is the most important part of an investigation.', ['it sets the focus, scope and direction for all research', 'a weak question cannot be rescued by good research'], ['good sources, methods and analysis are equally necessary', 'questions are often refined during the investigation'], 'It is the foundation of a good investigation, but its value depends on being refined and supported by sound methods and analysis.')],
     src=[('Student reflection (paraphrased)', 'My first question was "What is climate change?" My teacher said it was too broad. I changed it to "How has the length of the dry season changed in Chennai since 1990?" Now I could find rainfall data from the Indian Meteorological Department and compare it with news reports.', 'Reflection written by a Grade 8 student in an MYP I&S process journal, 2024', 'to reflect on how the research question developed during the investigation (criterion B iv)', 'It shows a real example of refining a question and choosing sources to fit it.', 'It is one student\'s account and does not show the final quality of the investigation.', 'Narrowing the question made it possible to use specific data and sources.')],
     rq=[('How has the number of street trees in our neighbourhood changed between 2015 and 2025?', 'Are trees good?', 'it is a closed question that cannot be investigated with evidence', 'It links to sustainability, uses data from city records and satellite images, and has a clear scope.', 'Week 1: find council tree records and Google Earth images; Week 2: count trees on five streets; Week 3: interview a council officer; record in a log; graph results; evaluate accuracy.'),
         ('Why did the population of Detroit fall between 1950 and 2020?', 'What happened in America?', 'it is far too broad and has no focus on a place or concept', 'It investigates causation of urban decline with census data and secondary sources.', 'Collect US census data; read two secondary sources on deindustrialisation and segregation; build a timeline; graph population; evaluate sources; cite in APA.'),
         ('How effective were the Thames Barrier closures in protecting London from tidal flooding in the winter of 2013–14?', 'Does London flood?', 'it is a yes/no question with no evaluative focus', 'It evaluates a real management strategy using official data on closures and flood events.', 'Collect Environment Agency closure data; read news reports; compare tide levels with barrier closures; evaluate data reliability; present findings in a timeline and table.')])
