     terms=[('bibliography', 'an alphabetical list of all the sources used in an investigation, written in a recognised format such as MLA or APA'),
            ('in-text citation', 'a short reference in the body of the work, such as (Frankopan 2015), that points to the full entry in the bibliography'),
            ('plagiarism', 'presenting someone else\'s words or ideas as your own without acknowledging them'),
            ('paraphrase', 'putting someone else\'s ideas into your own words, while still citing the source'),
            ('Cornell notes', 'a note-taking method that divides the page into a notes column, a cue column of key questions and a summary'),
            ('quantitative data', 'information in the form of numbers, such as population or rainfall figures'),
            ('qualitative data', 'descriptive information such as interviews, photographs or opinions')],
     facts=[('Which of these is quantitative data?', 'The number of cars passing a point in ten minutes', ['A resident\'s opinion of traffic', 'A photograph of a street', 'A diary entry'], 'Quantitative data are numerical.'),
            ('In MLA style, where is the author\'s surname placed in a book entry?', 'At the start, followed by a comma and the first name', ['At the end', 'After the title', 'It is left out'], 'e.g. Frankopan, Peter.'),
            ('Why should you record the source details when you take notes?', 'So you can cite every source accurately later', ['To make notes longer', 'Because teachers like lists', 'It is not necessary'], 'It avoids accidental plagiarism.'),
            ('Which of these is a primary source for a study of your town\'s traffic?', 'Your own traffic count', ['A textbook on urban geography', 'A Wikipedia article', 'A documentary about New York'], 'You collected it first-hand.')],
     why=[('Explain why citing sources is important in an investigation.', 'It gives credit to other people\'s work, avoids plagiarism, lets readers check and follow up the evidence, and shows the range and quality of research (criterion C iii).'),
          ('Explain why paraphrasing is often better than copying long quotations into notes.', 'Putting ideas in your own words shows you understand them and helps you use them in your argument; you must still cite the source.'),
          ('Explain why it is useful to collect both quantitative and qualitative data.', 'Numbers show patterns and size (how much, how many), while interviews and observations explain reasons and experiences, giving a fuller answer.'),
          ('Explain why a source log saves time at the end of an investigation.', 'Recording author, title, date, publisher or URL as you go means the bibliography can be built quickly and accurately, with no lost sources.')],
     contrast=[('quantitative data', 'qualitative data', 'Quantitative data are numerical (counts, measurements); qualitative data are descriptive (interviews, photos, opinions).'),
               ('a paraphrase', 'a quotation', 'A quotation uses the author\'s exact words in quotation marks; a paraphrase restates the ideas in your own words. Both must be cited.')],
     misc=[('If you change a few words, you do not need to cite the source.', 'Ideas taken from a source must be cited even when paraphrased; changing words does not make them your own.'),
           ('Information on the internet is free to use without citing.', 'Online information has authors and must be cited like any other source.'),
           ('A bibliography only needs to list books.', 'It must include every source used – websites, interviews, videos, maps and data sets as well as books.')],
     cases=[('a fieldwork survey of shopping habits', 'A student recorded 50 questionnaire responses in a spreadsheet and kept interview quotes in a separate notes file, each with date and location.', 'recording information systematically', 'organised records made the data easy to analyse and cite.'),
            ('Cornell notes on a documentary about the Amazon', 'A student wrote key facts in the notes column, questions in the cue column and a three-sentence summary, with the documentary\'s title, producer and year at the top.', 'effective note-taking', 'structured notes linked information to questions and recorded the source for citation.')],
